<?php
require_once dirname(__DIR__).'/app/bootstrap.php';$slug=trim((string)($_GET['slug']??''));$s=db()->prepare("SELECT g.*,u.name creator FROM guides g JOIN users u ON u.id=g.user_id WHERE g.slug=:s AND g.status='published'");$s->execute([':s'=>$slug]);$guide=$s->fetch();if(!$guide){http_response_code(404);$pageTitle='Guide not found';include __DIR__.'/includes/header.php';echo '<main id="main" class="container account-page"><h1>Guide not found</h1><a class="button button-primary" href="community.php">Back to community</a></main>';include __DIR__.'/includes/footer.php';exit;}$st=db()->prepare("SELECT l.* FROM guide_items gi JOIN listings l ON l.id=gi.listing_id WHERE gi.guide_id=:g AND l.status='published' ORDER BY gi.position");$st->execute([':g'=>$guide['id']]);$listings=$st->fetchAll();$pageTitle=$guide['title'].' | '.setting('site_name','MetroGuide');$pageDescription=text_excerpt($guide['description'],155,'');include __DIR__.'/includes/header.php';?>
<main id="main" class="container account-page"><div class="page-intro"><span class="eyebrow">COMMUNITY CITY GUIDE · <?= h($guide['city']) ?></span><h1><?= h($guide['title']) ?></h1><p><?= nl2br(h($guide['description'])) ?></p><small>Curated by <?= h($guide['creator']) ?> · <?= h(format_date($guide['created_at'])) ?></small></div><div class="listing-grid"><?php foreach($listings as $listing)include __DIR__.'/includes/listing-card.php'; ?></div><a class="button button-outline" href="community.php">Back to community</a></main><?php include __DIR__.'/includes/footer.php'; ?>
